using System;using System.IO;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioAnchorSizeValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static MashBoxStudioViewport view;static StudioModelEditor editor;static StudioModelDocument doc;static int stage,checks,lastPick=-2,small,normal;static float original;static double next;static string report;static Color[] rendered;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../anchor-size-result.txt"));try{original=StudioSettings.Current.handleSize;doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(new StudioModelDocument.Node{name="Stem_Anchor",anchorType="Stem_Anchor"});editor=new StudioModelEditor(()=>{if(view)view.MarkDirty(MashBoxStudioViewport.DirtyState.All);});editor.Load(doc);view=ScriptableObject.CreateInstance<MashBoxStudioViewport>();view.position=new Rect(80,80,700,600);view.Bind(editor.Scene);view.Show();view.LookAtDirect(Vector3.zero,Quaternion.Euler(25,35,0),3);SceneView.duringSceneGui+=Draw;StudioSettings.Current.handleSize=.5f;next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static void Draw(SceneView scene){if(scene!=view||Event.current.type!=EventType.Repaint)return;try{typeof(StudioModelEditor).GetMethod("DrawAnchorMarkers",F).Invoke(editor,new object[]{view});var center=HandleUtility.WorldToGUIPoint(editor.Transforms[0].position);typeof(StudioModelEditor).GetField("end",F).SetValue(editor,center+Vector2.right*25);lastPick=(int)typeof(StudioModelEditor).GetMethod("PickAnchors",F).Invoke(editor,new object[]{view,new Rect(),true});RenderMarker();}catch(Exception e){Finish(e.ToString());}}
 static void RenderMarker(){var rt=new RenderTexture(700,600,24);rt.Create();var texture=new Texture2D(700,600,TextureFormat.RGBA32,false,true);var old=RenderTexture.active;var oldTarget=view.camera.targetTexture;var oldRect=view.camera.pixelRect;GL.PushMatrix();try{view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,700,600);Handles.SetCamera(new Rect(0,0,700,600),view.camera);RenderTexture.active=rt;GL.Viewport(new Rect(0,0,700,600));GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;typeof(StudioModelEditor).GetMethod("DrawAnchorMarkers",F).Invoke(editor,new object[]{view});texture.ReadPixels(new Rect(0,0,700,600),0,0);texture.Apply();rendered=texture.GetPixels();}finally{view.camera.targetTexture=oldTarget;view.camera.pixelRect=oldRect;Handles.SetCamera(view.camera);GL.PopMatrix();RenderTexture.active=old;Object.DestroyImmediate(texture);Object.DestroyImmediate(rt);}}
 static int Snapshot(string name){Check(rendered!=null,"Native draw callback did not render");var texture=new Texture2D(700,600,TextureFormat.RGBA32,false,true);texture.SetPixels(rendered);texture.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../anchor-size-"+name+".png")),texture.EncodeToPNG());Object.DestroyImmediate(texture);float peak=0;foreach(var color in rendered)if(color.g>color.r*1.15f&&color.b>color.r*1.15f)peak=Math.Max(peak,color.b);int partial=0;foreach(var color in rendered)if(color.g>color.r*1.15f&&color.b>color.r*1.15f&&color.b>peak*.05f&&color.b<peak*.95f)partial++;Check(partial>0,"Anchor stroke has no antialiased coverage pixels");int minX=700,maxX=-1,minY=600,maxY=-1;for(int y=0;y<600;y++)for(int x=0;x<700;x++){var c=rendered[y*700+x];if(c.b>peak*.15f&&c.g>c.r*1.15f&&c.b>c.r*1.15f){minX=Math.Min(minX,x);maxX=Math.Max(maxX,x);minY=Math.Min(minY,y);maxY=Math.Max(maxY,y);}}Check(maxX>=minX,"No rendered anchor pixels at "+name+" pick="+lastPick+" type="+doc.nodes[0].anchorType+" z="+view.camera.WorldToViewportPoint(Vector3.zero).z);return Math.Max(maxX-minX+1,maxY-minY+1);}
 static void Paint(){view.MarkDirty(MashBoxStudioViewport.DirtyState.All);view.SendEvent(new Event{type=EventType.Layout});view.SendEvent(new Event{type=EventType.Repaint});}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.3;try{Paint();switch(stage++){
 case 0:small=Snapshot("half");Check(lastPick==-1,"Half-size anchor retained oversized click target");StudioSettings.Current.handleSize=1;break;
 case 1:normal=Snapshot("normal");Check(normal>small&&normal>=22,"Default marker did not grow or arms remain too short");Check(lastPick==0,"Default anchor click target changed");StudioSettings.Current.handleSize=2;break;
 case 2:int large=Snapshot("double");Check(large>normal&&large>small*2.5,"Rendered marker does not follow size multiplier");Check(lastPick==0,"Large anchor is not clickable beyond small hit radius");Check(doc.nodes.Count==1&&doc.nodes[0].position==Vector3.zero&&editor.Transforms[0].position==Vector3.zero,"Sizing changed anchor data");if(!view.orthographic){view.orthographic=true;StudioSettings.Current.handleSize=.5f;stage=0;}else Finish("PASS "+checks+" native rendered AA/size/picking anchor checks; ortho spans="+small+","+normal+","+large);break;
 }}catch(Exception e){Finish(e.ToString());}}
 static void Finish(string result){EditorApplication.update-=Tick;SceneView.duringSceneGui-=Draw;StudioSettings.Current.handleSize=original;File.WriteAllText(report,result);bool ok=result.StartsWith("PASS");if(view)view.Close();editor?.Dispose();if(doc)Object.DestroyImmediate(doc);EditorApplication.delayCall+=()=>EditorApplication.Exit(ok?0:1);}
}
